script:
(function () {
  'use strict';
  // Interest-only mortgage.
  //   During the interest-only period: payment = balance * rate / 12 (+ any extra principal).
  //   After it: the balance left is repaid over the remaining months,
  //   M = B * i / (1 - (1 + i)^-n), i = rate / 12, n = months left (M = B / n at 0%).
  //   Comparison: a standard loan for the same amount and full term at the comparison rate.
  // Verified in Node (scratchpad tests/w2b): $300,000 at 6.5%, 30 yrs, 10 yrs interest-only =
  //   $1,625.00/mo, then $2,236.72/mo (closed form over 240 months), total interest $431,812.66
  //   (= 120 * 1,625 + 240 * 2,236.72 - 300,000); standard loan $1,896.20/mo, $382,633.47 interest;
  //   $200/mo extra principal leaves $276,000 and a $2,057.78 payment; paying $5,000/mo extra clears
  //   the loan in 60 months with $49,562.50 interest (arithmetic series); 0% rate = $0 then $1,250/mo;
  //   no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  function interestOnly(loan, rate, months, ioMonths, extra) {
    var bal = loan, i = rate / 1200, rows = [], total = 0, pay = 0, balAtReset = loan;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i, principal;
      if (m <= ioMonths) {
        principal = Math.min(extra, bal);
      } else {
        if (m === ioMonths + 1) { balAtReset = bal; pay = payment(bal, rate, months - ioMonths); }
        principal = m === months ? bal : Math.min(pay - interest, bal);
      }
      bal -= principal;
      if (bal < 0.005) bal = 0;
      total += interest;
      rows.push({ n: m, payment: interest + principal, principal: principal, interest: interest, balance: bal });
    }
    if (ioMonths >= rows.length) balAtReset = bal;
    return { ioPay: loan * i, laterPay: pay, balAtReset: balAtReset, totalInterest: total, rows: rows };
  }

  function clearResults() {
    ['ioPay', 'ioLaterPay', 'ioJump', 'ioTotalInterest', 'ioBalanceAtReset', 'ioResetWhen', 'ioTotalPaid', 'ioStdPay',
     'ioStdInterest', 'ioExtraCost'].forEach(function (id) { setText(id, '–'); });
    el('ioSchedule').innerHTML = '';
  }

  function update() {
    var loan = read('ioLoan'), rate = read('ioRate'), years = read('ioTerm'), ioYears = read('ioYears'),
        extra = read('ioExtra', true), cmpRate = read('ioCompareRate');
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(years) || years < 2 || years > 40 || years % 1 !== 0) msg = 'Enter a loan term of 2 to 40 whole years.';
    else if (isNaN(ioYears) || ioYears < 1 || ioYears % 1 !== 0 || ioYears >= years) msg = 'Enter an interest-only period of at least 1 whole year that is shorter than the loan term.';
    else if (isNaN(extra) || extra < 0) msg = 'Extra principal cannot be negative.';
    else if (isNaN(cmpRate) || cmpRate < 0 || cmpRate > 30) msg = 'Enter a comparison rate from 0% to 30%.';
    var error = el('ioError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var months = years * 12, ioMonths = ioYears * 12;
    var r = interestOnly(loan, rate, months, ioMonths, extra);
    var stdPay = payment(loan, cmpRate, months);
    var stdInterest = stdPay * months - loan;
    if (cmpRate === 0) stdInterest = 0;

    setText('ioPay', money.format(r.ioPay));
    setText('ioLaterPay', money.format(r.laterPay));
    var jump = r.laterPay - r.ioPay;
    setText('ioJump', r.ioPay > 0 ? money.format(jump) + ' (' + (jump >= 0 ? '+' : '') + Math.round(jump / r.ioPay * 100) + '%)' : money.format(jump));
    setText('ioTotalInterest', money.format(r.totalInterest));
    setText('ioBalanceAtReset', money.format(r.balAtReset));
    setText('ioResetWhen', r.rows.length > ioMonths ? String(ioMonths + 1) : 'Paid off during the interest-only period');
    setText('ioTotalPaid', money.format(loan + r.totalInterest));
    setText('ioStdPay', money.format(stdPay));
    setText('ioStdInterest', money.format(stdInterest));
    setText('ioExtraCost', money.format(r.totalInterest - stdInterest));

    var html = [], p = 0, intr = 0;
    r.rows.forEach(function (row, idx) {
      p += row.principal; intr += row.interest;
      if (row.n % 12 === 0 || idx === r.rows.length - 1) {
        html.push('<tr><td>' + Math.ceil(row.n / 12) + '</td><td>' + money.format(row.payment) + '</td><td>' + money.format(p) +
          '</td><td>' + money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
        p = 0; intr = 0;
      }
    });
    el('ioSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('ioForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
